mapper.select:
SELECT a.id AS asn_id, a.asn_no AS asn_no, a.status AS asn_status, a.logistics_company AS logistics_company, a.tracking_no AS tracking_no, a.eta_date AS eta_date, a.ship_qty AS shipped_qty, a.create_time AS create_time, o.id AS order_id, o.order_no AS system_order_no, o.order_no AS sap_order_no, o.supplier_id AS supplier_id, o.supplier_no AS supplier_duns, o.supplier_name AS supplier_name, o.storage_name AS ship_to_plant, o.address AS ship_to_address, d.parts_number AS parts_no, d.parts_name AS parts_name, a.ship_date AS ship_date, a.actual_eta_date AS actual_eta_date, a.warehouse_in_no AS warehouse_in_no, d.storage_name AS storage_name FROM tb_srm_asn a LEFT JOIN tb_srm_asn_order ao ON a.id = ao.asn_id LEFT JOIN tb_purchase_parts_order o ON ao.order_id = o.id LEFT JOIN tb_purchase_parts_order_detail d ON a.order_detail_id = d.id WHERE 1=1 AND IFNULL(a.is_deleted, 0) = 0
AND a.asn_no IN
#{asnNo}
AND o.supplier_no IN
#{supplierNo}
AND o.order_no IN
#{orderNo}
AND o.order_no IN
#{sapOrderNo}
AND a.status = #{shippedFlag}
AND d.parts_number IN
#{partsNo}
AND a.actual_eta_date = #{actualEtaDate}
ORDER BY a.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT a.id AS asn_id, a.asn_no AS asn_no, a.status AS asn_status, a.logistics_company AS logistics_company, a.tracking_no AS tracking_no, a.eta_date AS eta_date, a.ship_qty AS shipped_qty, a.create_time AS create_time, o.id AS order_id, o.order_no AS system_order_no, o.order_no AS sap_order_no, o.supplier_id AS supplier_id, o.supplier_no AS supplier_duns, o.supplier_name AS supplier_name, o.storage_name AS ship_to_plant, o.address AS ship_to_address, d.parts_number AS parts_no, d.parts_name AS parts_name, a.ship_date AS ship_date, a.actual_eta_date AS actual_eta_date, a.warehouse_in_no AS warehouse_in_no, d.storage_name AS storage_name FROM tb_srm_asn a LEFT JOIN tb_srm_asn_order ao ON a.id = ao.asn_id LEFT JOIN tb_purchase_parts_order o ON ao.order_id = o.id LEFT JOIN tb_purchase_parts_order_detail d ON a.order_detail_id = d.id WHERE 1=1 AND IFNULL(a.is_deleted, 0) = 0 AND a.supplier_id = #{supplierId}
AND a.asn_no IN
#{asnNo}
AND o.supplier_no IN
#{supplierNo}
AND o.order_no IN
#{orderNo}
AND o.order_no IN
#{sapOrderNo}
AND a.status = #{shippedFlag}
AND d.parts_number IN
#{partsNo}
AND a.actual_eta_date = #{actualEtaDate}
ORDER BY a.id DESC LIMIT #{limit} OFFSET #{offset}

